function applyReaderPrefs(){const themes={paper:['#ffffff','#292724'],sepia:['#f2e8d2','#443b2b'],night:['#1d2021','#d8d7d2']};const colors=themes[prefs.theme]||themes.paper;$('#reader').style.setProperty('--reader-bg',colors[0]);$('#reader').style.setProperty('--reader-ink',colors[1]);$('#book-content').style.fontSize=prefs.size+'px';$('#book-content').style.lineHeight=String(prefs.line);$('#book-content').style.maxWidth=prefs.width+'px';const fonts={serif:"Georgia,'Times New Roman',serif",times:"'Times New Roman',Times,serif",palatino:"'Palatino Linotype',Palatino,'Book Antiqua',Georgia,serif",charter:"Charter,'Bitstream Charter',Georgia,serif",sans:"FolioSans,'Avenir Next',Arial,sans-serif",system:"system-ui,-apple-system,'Segoe UI',Roboto,sans-serif",mono:"ui-monospace,'Cascadia Code',Consolas,monospace"};$('#book-content').style.fontFamily=fonts[prefs.font]||fonts.serif;$('#pdf-canvas').style.filter=prefs.theme==='night'?'invert(.87) hue-rotate(180deg)':prefs.theme==='sepia'?'sepia(.25)':'none';}
async function openBook(id,sampleData){if(active)await closeReader();const b=sampleData?.book||books.find(x=>x.id===id);if(!b)return;$('#import-progress').hidden=false;$('#import-message').textContent='Đang mở sách…';try{const c=sampleData?.content||await getContent(id);if(!c)throw new Error('Không tìm thấy nội dung đã lưu. Hãy nhập lại tệp sách.');active=b;content=c;chapter=Math.min(Math.max(b.chapter||0,0),c.chapters.length-1);if(b.format==='PDF')pdf=await loadPDF(await c.original.arrayBuffer());b.lastRead=Date.now();if(b.status==='unread')b.status='reading';await metadataSave(b);$('#reader-title').textContent=b.title;$('#reader-author').textContent=b.author+(b.sample?' · Trang đọc thử':'');$('#library').hidden=true;$('#reader').hidden=false;document.body.style.overflow='hidden';applyReaderPrefs();await renderChapter(chapter,b.offset||0);$('#reading-viewport').focus();lastActivity=Date.now();}catch(e){active=null;content=null;$('#library').hidden=false;$('#reader').hidden=true;document.body.style.overflow='';throw e;}finally{$('#import-progress').hidden=true;}}
