on('#reader-search','click',()=>{panel('Tìm trong sách',`<label for="book-search">Từ hoặc cụm từ</label><input id="book-search" type="search" placeholder="Nhập ít nhất 2 ký tự…"><p id="search-count"></p><div id="search-results"></div>`);let timer;on('#book-search','input',e=>{clearTimeout(timer);const term=e.target.value.trim();timer=setTimeout(()=>{if(!$('#search-results')||!active)return;if(term.length<2){$('#search-results').innerHTML='';$('#search-count').textContent='';return;}const results=[];for(let i=0;i<content.chapters.length;i++){const text=content.chapters[i].text||'',lower=text.toLocaleLowerCase('vi'),needle=term.toLocaleLowerCase('vi');let pos=0,idx;while((idx=lower.indexOf(needle,pos))>=0&&results.length<150){results.push({chapter:i,index:idx,text:text.slice(Math.max(0,idx-55),idx+term.length+95)});pos=idx+needle.length;}if(results.length>=150)break;}$('#search-count').textContent=results.length?`${results.length}${results.length===150?'+':''} kết quả`:'Không tìm thấy kết quả.';$('#search-results').innerHTML=results.map((r,i)=>`<button class="result-entry" data-search-result="${i}">${esc(r.text)}<small>${esc(content.chapters[r.chapter].title)}</small></button>`).join('');$('#search-results').onclick=async e=>{const b=e.target.closest('[data-search-result]');if(!b)return;const r=results[+b.dataset.searchResult];closePanel();try{if(active.format==='PDF')prefs.pdfText=true;await renderChapter(r.chapter);const range=textRange(r.index,r.index+term.length);if(range){const sel=getSelection();sel.removeAllRanges();sel.addRange(range);range.startContainer.parentElement.scrollIntoView({block:'center'});}}catch(error){fail(error);}};},200);});$('#book-search').focus();});
function download(blob,name){const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function exportBackup(){if(busy)return;if(books.reduce((n,b)=>n+b.size,0)>150*1024*1024)throw new Error('Bản sao lưu hỗ trợ tối đa 150 MB tệp gốc. Hãy tải tệp gốc của các sách lớn trước khi giảm dung lượng thư viện.');busy=true;$('#import-progress').hidden=false;$('#import-message').textContent='Đang tạo bản sao lưu…';try{const zip=new JSZip();const manifest={version:1,app:'folio',exported:new Date().toISOString(),collections,reader:prefs,goal,daily,books:[]};for(const b of books){const c=await getContent(b.id);const path=`books/${b.id}.${b.format.toLowerCase()}`;zip.file(path,await c.original.arrayBuffer());manifest.books.push({...b,path});}zip.file('folio.json',JSON.stringify(manifest,null,2));download(await zip.generateAsync({type:'blob',compression:'STORE'}),`folio-backup-${dayKey()}.zip`);toast('Đã tạo bản sao lưu sách, dấu trang và ghi chú.');}finally{busy=false;$('#import-progress').hidden=true;}}
async function restoreBackup(file){if(!file||busy)return;if(file.size>200*1024*1024)throw new Error('Bản sao lưu tối đa 200 MB.');busy=true;$('#import-progress').hidden=false;let count=0,skipped=0;try{const zip=await JSZip.loadAsync(await file.arrayBuffer());checkZip(zip);const metaFile=zip.file('chang.json')||zip.file('folio.json');if(!metaFile)throw new Error('Đây không phải bản sao lưu hợp lệ.');const data=JSON.parse(await metaFile.async('string'));if(data.version!==1||!['folio','chang'].includes(data.app)||!Array.isArray(data.books)||data.books.length>1000)throw new Error('Bản sao lưu không hợp lệ.');for(const meta of data.books){if(typeof meta.path!=='string'||!zip.file(meta.path))throw new Error('Bản sao lưu thiếu tệp sách.');if(books.some(b=>b.id===meta.id)){skipped++;continue;}$('#import-message').textContent=`Khôi phục ${count+1}: ${String(meta.title).slice(0,100)}`;const file=new File([await zip.file(meta.path).async('uint8array')],String(meta.filename||meta.path));const parsed=await parseBook(file);if(parsed.book.id!==meta.id)throw new Error('Nội dung sách không khớp mã kiểm tra.');const b=parsed.book;if(typeof meta.title==='string'&&meta.title.trim())b.title=meta.title.trim().slice(0,200);if(typeof meta.author==='string')b.author=meta.author.trim().slice(0,150)||'Chưa rõ tác giả';if(meta.cover===null)b.cover=null;else if(validCover(meta.cover))b.cover=meta.cover;b.favorite=meta.favorite===true;b.collection=typeof meta.collection==='string'?meta.collection.slice(0,60):'';b.status=['unread','reading','finished'].includes(meta.status)?meta.status:'unread';b.chapter=Math.max(0,Math.min(b.chapterCount-1,Number(meta.chapter)||0));b.offset=Math.max(0,Math.min(1,Number(meta.offset)||0));b.progress=Math.max(0,Math.min(1,Number(meta.progress)||0));b.lastRead=Number(meta.lastRead)||0;b.bookmarks=(Array.isArray(meta.bookmarks)?meta.bookmarks:[]).filter(x=>Number.isInteger(x.chapter)&&x.chapter>=0&&x.chapter<b.chapterCount).map(x=>({id:crypto.randomUUID(),chapter:x.chapter,offset:Math.max(0,Math.min(1,Number(x.offset)||0)),label:String(x.label||'Dấu trang').slice(0,300),date:Date.now()}));b.notes=(Array.isArray(meta.notes)?meta.notes:[]).filter(x=>Number.isInteger(x.chapter)&&x.chapter>=0&&x.chapter<b.chapterCount&&Number.isInteger(x.start)&&Number.isInteger(x.end)&&x.start>=0&&x.end>x.start&&x.end<=parsed.content.chapters[x.chapter].text.length).map(x=>({id:crypto.randomUUID(),chapter:x.chapter,start:x.start,end:x.end,quote:String(x.quote||'').slice(0,50000),note:String(x.note||'').slice(0,10000),date:Date.now()}));await addBook(b,parsed.content);books.push(b);if(b.collection&&!collections.includes(b.collection))collections.push(b.collection);count++;}if(Array.isArray(data.collections))collections=[...new Set([...collections,...data.collections.filter(x=>typeof x==='string'&&x.length<=60&&!['all','reading','favorites','finished'].includes(x))])];await setSetting('collections',collections);if(Number.isInteger(data.goal)&&data.goal>=1&&data.goal<=240){goal=data.goal;await setSetting('goal',goal);}if(data.reader&&typeof data.reader==='object'){const r=data.reader;if(['paper','sepia','night'].includes(r.theme))prefs.theme=r.theme;if(['serif','times','palatino','charter','sans','system','mono'].includes(r.font))prefs.font=r.font;if(Number.isFinite(r.size)&&r.size>=14&&r.size<=36)prefs.size=r.size;if(Number.isFinite(r.line)&&r.line>=1.3&&r.line<=2.5)prefs.line=r.line;if(Number.isFinite(r.width)&&r.width>=480&&r.width<=1000)prefs.width=r.width;prefs.pdfText=r.pdfText===true;await setSetting('reader',prefs);}if(data.daily&&typeof data.daily==='object'){for(const [key,value]of Object.entries(data.daily)){if(/^\d{4}-\d{2}-\d{2}$/.test(key)&&Number.isFinite(value)&&value>=0&&value<=86400)daily[key]=Math.max(daily[key]||0,value);}await setSetting('daily',daily);}renderLibrary();toast(`Đã khôi phục ${count} sách${skipped?` · Giữ nguyên ${skipped} sách đã có`:''}.`);closePanel();}finally{busy=false;$('#import-progress').hidden=true;$('#backup-input').value='';renderLibrary();}}
on('#backup-input','change',e=>restoreBackup(e.target.files[0]));
async function settingsPanel(){const estimate=await navigator.storage?.estimate?.().catch(()=>null);const persistent=await navigator.storage?.persisted?.().catch(()=>false);panel('Dữ liệu & cài đặt',`<p>Sách và ghi chú được lưu trong trình duyệt này, trên thiết bị này. Không đồng bộ sang trình duyệt hoặc thiết bị khác.</p><div class="storage-box"><strong>${books.length} cuốn sách · ${formatSize(books.reduce((n,b)=>n+b.size,0))} tệp gốc</strong>${estimate?`<br>Đã dùng ${formatSize(estimate.usage||0)} / ${formatSize(estimate.quota||0)} dung lượng trình duyệt`:''}<br>${persistent?'Đã được cấp lưu trữ bền vững':'Chưa được cấp lưu trữ bền vững'}</div><p>Xóa dữ liệu trang web hoặc dùng chế độ riêng tư có thể làm mất thư viện. Hãy giữ tệp gốc và sao lưu định kỳ.</p><button id="persist-storage" class="button full">${icon('lock')}Ưu tiên giữ dữ liệu trên thiết bị</button><h3>Sao lưu & khôi phục</h3><p>Bản ZIP gồm tệp sách gốc, tiến độ, bộ sưu tập, dấu trang và ghi chú. Khi khôi phục, sách đã có được giữ nguyên.</p><button id="export-backup" class="button primary full">${icon('download')}Xuất bản sao lưu (${books.length} sách)</button><button id="restore-backup" class="button full">${icon('upload')}Khôi phục từ bản sao lưu</button><h3>Mục tiêu đọc mỗi ngày</h3><label for="goal-setting">Số phút</label><input type="number" id="goal-setting" min="1" max="240" value="${goal}"><button id="save-goal" class="button full">Lưu mục tiêu</button><h3>Bộ sưu tập</h3><button id="settings-new-collection" class="button full">${icon('plus')}Tạo bộ sưu tập</button>${collections.length?`<label for="delete-collection-select">Xóa bộ sưu tập (giữ lại sách)</label><select id="delete-collection-select">${collections.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select><button id="delete-collection" class="text-button danger-text">Xóa bộ sưu tập đã chọn</button>`:''}<hr><p><strong>Định dạng hỗ trợ:</strong> EPUB không khóa DRM, PDF, TXT UTF-8, Markdown cơ bản, HTML và FB2. MOBI/AZW và sách có DRM chưa được hỗ trợ.</p><button id="settings-sample" class="text-button">Mở trang đọc thử ${icon('arrow')}</button>`);
 on('#persist-storage','click',async()=>{const ok=await navigator.storage?.persist?.();toast(ok?'Đã được trình duyệt ưu tiên giữ dữ liệu.':'Trình duyệt chưa cấp quyền lưu bền vững. Hãy giữ bản sao lưu.');});on('#export-backup','click',exportBackup);on('#restore-backup','click',()=>$('#backup-input').click());on('#save-goal','click',async()=>{const value=Number($('#goal-setting').value);if(!Number.isInteger(value)||value<1||value>240){toast('Chọn từ 1 đến 240 phút.');return;}goal=value;await setSetting('goal',goal);updateGoal();toast('Đã lưu mục tiêu đọc.');});on('#settings-new-collection','click',newCollection);on('#settings-sample','click',async()=>{closePanel();await openSample();});if(collections.length)on('#delete-collection','click',async()=>{const name=$('#delete-collection-select').value;for(const b of books.filter(b=>b.collection===name)){b.collection='';await metadataSave(b);}collections=collections.filter(x=>x!==name);await setSetting('collections',collections);if(filter===name)filter='all';renderLibrary();await settingsPanel();});}
on('#storage-settings','click',settingsPanel);on('#mobile-settings','click',settingsPanel);on('#goal-edit','click',settingsPanel);
const sampleChapters=[{title:'Một khoảng lặng để đọc',html:'<h1>Một khoảng lặng để đọc</h1><p>Giữa một ngày nhiều thông báo, đôi khi điều ta cần chỉ là một trang sách và vài phút không bị ngắt quãng.</p><p>Chang Book Reader bắt đầu từ ý nghĩ ấy. Không có bảng tin cần kéo mãi. Không có cửa hàng chờ bạn mua thêm. Chỉ có những cuốn sách bạn chọn và những trang đang đợi được mở ra.</p><h2>Cuốn sách nằm lại đây</h2><p>Khi nhập một cuốn sách, bản sao của nó được giữ ngay trong trình duyệt trên thiết bị này. Bạn có thể đóng trang, quay lại, và tiếp tục ở vị trí đã dừng.</p><p>Thử chọn câu này để tô sáng hoặc thêm một ghi chú. Những điều bạn muốn nhớ đôi khi chỉ cần một dấu nhỏ bên lề.</p><h2>Đọc theo nhịp của mình</h2><p>Nhấn Aa trên thanh công cụ để đổi cỡ chữ, giãn dòng hoặc màu nền. Một trang giấy sáng cho buổi ban mai. Một nền dịu cho buổi chiều. Một khoảng tối vừa đủ khi căn phòng đã yên.</p><p>Không cần đọc thật nhanh. Cũng không cần đọc hết một chương. Một vài trang mỗi ngày vẫn là một cách đi xa.</p>'},{title:'Mang theo những trang đã đọc',html:'<h1>Mang theo những trang đã đọc</h1><p>Một thư viện riêng không nhất thiết phải lớn. Nó có thể chỉ là một cuốn truyện đã đọc nhiều lần, một tài liệu đang học, và một cuốn sách dành cho ngày chưa đến.</p><h2>Những dấu mốc nhỏ</h2><p>Dùng dấu trang để giữ một vị trí. Dùng ghi chú để giữ một ý nghĩ. Tìm kiếm để quay lại một câu đã khiến bạn dừng lâu hơn.</p><p>Sách không tự được đồng bộ giữa các thiết bị. Trong Dữ liệu &amp; cài đặt, bạn có thể xuất toàn bộ thư viện thành một tệp sao lưu và nhập nó trên trình duyệt khác.</p><h2>Trang tiếp theo là của bạn</h2><p>Đây là nội dung đọc thử được viết cho Chang Book Reader, không phải sách được nhập vào thư viện. Tiến độ và ghi chú trong trang thử chỉ tồn tại trong phiên này.</p><p>Trở về thư viện, chọn một tệp EPUB, PDF hoặc văn bản. Mở cuốn sách đầu tiên. Phần còn lại, cứ để từng trang dẫn đường.</p>'}];
async function openSample(){const chapters=sampleChapters.map((c,i)=>({...c,text:new DOMParser().parseFromString(c.html,'text/html').body.textContent,path:`sample-${i}`}));await openBook('sample',{book:{id:'sample',sample:true,title:'Một khoảng lặng để đọc',author:'Chang Book Reader',format:'TXT',chapter:0,offset:0,progress:0,status:'unread',bookmarks:[],notes:[]},content:{chapters,toc:chapters.map((c,index)=>({label:c.title,index,anchor:''}))}});}
document.querySelectorAll('.sample-trigger').forEach(b=>b.addEventListener('click',()=>openSample().catch(fail)));
document.addEventListener('keydown',e=>{lastActivity=Date.now();if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||$('#panel').open||$('#confirm-dialog').open)return;if(active){if(e.key==='ArrowRight'||e.key==='PageDown'){e.preventDefault();turnPage(1).catch(fail);}if(e.key==='ArrowLeft'||e.key==='PageUp'){e.preventDefault();turnPage(-1).catch(fail);}if(e.key==='Escape')closeReader().catch(fail);}else if(e.key==='/'){e.preventDefault();$('#library-search').focus();}});
document.addEventListener('pointerdown',()=>lastActivity=Date.now());let touchStart;$('#reading-viewport').addEventListener('touchstart',e=>{const t=e.touches[0];touchStart={x:t.clientX,y:t.clientY};},{passive:true});$('#reading-viewport').addEventListener('touchend',e=>{if(!touchStart||!getSelection().isCollapsed)return;const t=e.changedTouches[0],dx=t.clientX-touchStart.x,dy=t.clientY-touchStart.y;if(Math.abs(dx)>85&&Math.abs(dy)<50)turnPage(dx<0?1:-1).catch(fail);touchStart=null;},{passive:true});
setInterval(()=>{if(active&&!active.sample&&!document.hidden&&Date.now()-lastActivity<180000){const key=dayKey();daily[key]=(daily[key]||0)+1;readingSeconds++;if(readingSeconds%10===0)setSetting('daily',daily).catch(fail);updateGoal();}},1000);
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(active){capturePosition();metadataSave(active).catch(fail);}setSetting('daily',daily).catch(fail);}});
let forgeFormat='epub';
function updateForgePreview(){
  const title=$('#forge-title')?.value.trim()||'Tên sách';
  const author=$('#forge-author')?.value.trim()||'Tác giả';
  const text=$('#forge-text')?.value||'';
  const blocks=parseDraft(text,true);
  const words=text.trim()?text.trim().split(/\s+/u).filter(Boolean).length:0;
  const chapters=blocks.filter(b=>/^h[1-6]$/.test(b.type)).length;
  if($('#forge-word-count'))$('#forge-word-count').textContent=`${words.toLocaleString('vi-VN')} từ · ${text.length.toLocaleString('vi-VN')} ký tự`;
  if($('#forge-chapter-count'))$('#forge-chapter-count').textContent=`${chapters} chương mục`;
  if($('#forge-preview')){
    if(!text.trim()){
      $('#forge-preview').innerHTML='<em>Nội dung xem trước của sách sẽ hiển thị tại đây khi bạn nhập bản thảo…</em>';
    }else{
      $('#forge-preview').innerHTML=`<h1 style="font-size:1.5em;margin:0 0 6px">${esc(title)}</h1><p style="color:var(--muted);margin:0 0 14px"><em>${esc(author)}</em></p><hr style="border:0;border-top:1px solid var(--line);margin:14px 0">${renderBlocks(blocks.slice(0,80),true)}`;
    }
  }
}
function openForge(){$('#forge-dialog').showModal();icons($('#forge-dialog'));updateForgePreview();}
function initForge(){
  if($('#open-forge'))on('#open-forge','click',openForge);
  if($('#forge-btn'))on('#forge-btn','click',openForge);
  if($('#close-forge'))on('#close-forge','click',()=>$('#forge-dialog').close());
  if($('#forge-text'))on('#forge-text','input',updateForgePreview);
  if($('#forge-title'))on('#forge-title','input',updateForgePreview);
  if($('#forge-author'))on('#forge-author','input',updateForgePreview);
  if($('#forge-sample'))on('#forge-sample','click',()=>{
    $('#forge-title').value='Hành Trình Giản Dị';
    $('#forge-author').value='Chang Book Reader';
    $('#forge-text').value='# Chương 1: Một khởi đầu mới\n\nBuổi sáng thức dậy trong ánh nắng dịu dàng. Một cuốn sách bắt đầu từ **một ý tưởng nhỏ** nhưng tràn đầy cảm hứng.\n\n> "Hành trình vạn dặm bắt đầu từ một bước chân."\n\n## Những điều mang theo\n\n- Một cuốn sổ nhỏ\n- Tinh thần tò mò học hỏi\n- Một khoảng lặng bình yên để đọc\n\n# Chương 2: Những trang viết tiếp theo\n\nTừng trang sách mở ra những chân trời mới. Cuộc sống đẹp hơn khi chúng ta biết lắng nghe và suy ngẫm.';
    updateForgePreview();
  });
  if($('#forge-file-btn'))on('#forge-file-btn','click',()=>$('#forge-file-input').click());
  if($('#forge-file-input'))on('#forge-file-input','change',async e=>{
    const file=e.target.files[0];
    if(!file)return;
    const text=await file.text();
    $('#forge-text').value=text;
    if(!$('#forge-title').value.trim()){$('#forge-title').value=file.name.replace(/\.(txt|md|markdown)$/i,'');}
    updateForgePreview();
    toast(`Đã tải bản thảo: ${file.name}`);
  });
  if($('#forge-formats'))$('#forge-formats').onclick=e=>{
    const pill=e.target.closest('.format-pill');
    if(!pill)return;
    forgeFormat=pill.dataset.fmt;
    $('#forge-formats').querySelectorAll('.format-pill').forEach(p=>p.classList.toggle('active',p===pill));
  };
  if($('#forge-download-btn'))on('#forge-download-btn','click',()=>{
    const text=$('#forge-text').value;
    if(!text.trim()){toast('Vui lòng nhập hoặc chọn bản thảo.');return;}
    const title=$('#forge-title').value.trim()||'Cuon-sach';
    const author=$('#forge-author').value.trim()||'Chưa rõ tác giả';
    const bookObj={title,author,language:'vi',markdown:true,blocks:parseDraft(text,true)};
    try{
      const blob=convertBook(bookObj,forgeFormat);
      download(blob,`${title.replace(/[<>:"/\\|?*]/g,'_')}.${forgeFormat}`);
      toast(`Đã tạo và tải file ${forgeFormat.toUpperCase()}!`);
    }catch(err){fail(err);}
  });
  if($('#forge-library-btn'))on('#forge-library-btn','click',async()=>{
    const text=$('#forge-text').value;
    if(!text.trim()){toast('Vui lòng nhập hoặc chọn bản thảo.');return;}
    const title=$('#forge-title').value.trim()||'Sách mới';
    const author=$('#forge-author').value.trim()||'Chưa rõ tác giả';
    const bookObj={title,author,language:'vi',markdown:true,blocks:parseDraft(text,true)};
    try{
      $('#import-progress').hidden=false;
      $('#import-message').textContent='Đang đóng sách và nạp vào thư viện…';
      const epubBlob=convertBook(bookObj,'epub');
      const file=new File([await epubBlob.arrayBuffer()],`${title}.epub`,{type:'application/epub+zip'});
      const parsed=await parseBook(file);
      await addBook(parsed.book,parsed.content);
      books.unshift(parsed.book);
      renderLibrary();
      $('#forge-dialog').close();
      toast(`Đã thêm “${title}” vào thư viện!`);
      await openBook(parsed.book.id);
    }catch(err){fail(err);}finally{
      $('#import-progress').hidden=true;
    }
  });
}
async function init(){try{await openDatabase();[books,collections,prefs,goal,daily,view]=await Promise.all([getBooks(),getSetting('collections',[]),getSetting('reader',prefs),getSetting('goal',15),getSetting('daily',{}),getSetting('view','grid')]);document.body.classList.toggle('dark',await getSetting('dark',false));for(const mode of ['grid','list']){$(`#${mode}-view`).classList.toggle('active',view===mode);$(`#${mode}-view`).setAttribute('aria-pressed',String(view===mode));}renderLibrary();initForge();const ctx=document.modelContext;if(ctx?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'list_library_books',description:'List locally imported books and reading progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async()=>({books:books.map(({id,title,author,format,progress,status,collection})=>({id,title,author,format,progress,status,collection}))})},{name:'open_library_book',description:'Open one existing local book and restore its reading position.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async input=>{if(!input||typeof input.id!=='string'||!books.some(b=>b.id===input.id))throw new Error('Unknown book id');await openBook(input.id);return {opened:active.id,chapter,progress:active.progress};}}])try{await ctx.registerTool(tool,{signal:lifecycle.signal});}catch(e){console.warn('WebMCP unavailable',e);}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(e=>console.warn('Offline cache unavailable',e));}catch(e){panel('Không thể mở bộ nhớ sách',`<p>${esc(e.message)}</p><p>Hãy mở bằng một cửa sổ trình duyệt thông thường và cho phép trang lưu dữ liệu.</p>`);}}
init();
